    let payment_intent_ref01_data = setup.data.new.payment_intent['payment_intent_ref01']

    payment_intent_ref01_data = (await payment_intent_ref01_ent.create(payment_intent_ref01_data)).data()
    assert(null != payment_intent_ref01_data.id)


    // LIST
    const payment_intent_ref01_match = {}

    const payment_intent_ref01_list = (await payment_intent_ref01_ent.list(payment_intent_ref01_match)).map((e) => e.data())

    assert(!isempty(select(payment_intent_ref01_list, { id: payment_intent_ref01_data.id })))


    // LOAD
